package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Repository;

/** The store of the sheet's pools and their members. */
@Repository
public class Pools {

    /**
     * A stored member: the pool's name, the person's id (0 for a pool), the share, the member pool (null for a person),
     * and the from-date and to-date, both inclusive, each null when open-ended.
     */
    public record Membership(String pool, long personId, BigDecimal share, String memberPool, LocalDate from,
            LocalDate to) {

        /** Whether the membership's dates include the day. */
        public boolean on(LocalDate day) {
            return (from == null || !day.isBefore(from)) && (to == null || !day.isAfter(to));
        }
    }

    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(listed), 0) + 1 FROM (SELECT listed FROM pool_member "
            + "WHERE sheet_id = ? UNION ALL SELECT listed FROM pool_nested WHERE sheet_id = ?) l)";

    private final JdbcTemplate jdbc;

    public Pools(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's pool names, in the order they were added. */
    public List<String> names(String sheetId) {
        return jdbc.queryForList("SELECT name FROM pool WHERE sheet_id = ? ORDER BY listed", String.class, sheetId);
    }

    public boolean has(String sheetId, String name) {
        return names(sheetId).contains(name);
    }

    public void add(Pool pool) {
        jdbc.update("INSERT INTO pool (sheet_id, name, listed) VALUES (?, ?, "
                + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM pool WHERE sheet_id = ?))",
                pool.sheetId(), pool.name(), pool.sheetId());
    }

    /** The sheet's pool members, people and pools, in the order they were added. */
    public List<Membership> members(String sheetId) {
        return jdbc.query("SELECT pool_name, person_id, share, CAST(NULL AS VARCHAR(255)) AS member_pool, from_date, "
                + "to_date, listed FROM pool_member WHERE sheet_id = ? UNION ALL SELECT pool_name, 0, share, member_pool, "
                + "from_date, to_date, listed FROM pool_nested WHERE sheet_id = ? ORDER BY listed",
                (rs, n) -> new Membership(rs.getString("pool_name"), rs.getLong("person_id"),
                        rs.getBigDecimal("share").setScale(2), rs.getString("member_pool"),
                        rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)),
                sheetId, sheetId);
    }

    /** Each pool that is a member of another, to the pool it is a member of. */
    public Map<String, String> parents(String sheetId) {
        Map<String, String> out = new HashMap<>();
        jdbc.query("SELECT pool_name, member_pool FROM pool_nested WHERE sheet_id = ?",
                (RowCallbackHandler) rs -> out.put(rs.getString("member_pool"), rs.getString("pool_name")), sheetId);
        return out;
    }

    public boolean isMember(String sheetId, String pool, long personId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM pool_member WHERE sheet_id = ? AND pool_name = ? AND person_id = ?", Integer.class,
                sheetId, pool, personId);
        return n != null && n > 0;
    }

    public void addMember(PoolMember member) {
        if (member.memberPool() != null) {
            jdbc.update("INSERT INTO pool_nested (sheet_id, pool_name, member_pool, share, from_date, to_date, listed) "
                    + "VALUES (?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", member.sheetId(), member.pool(),
                    member.memberPool(), member.share(), member.from(), member.to(), member.sheetId(), member.sheetId());
            return;
        }
        jdbc.update("INSERT INTO pool_member (sheet_id, pool_name, person_id, share, from_date, to_date, listed) "
                + "VALUES (?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", member.sheetId(), member.pool(), member.personId(),
                member.share(), member.from(), member.to(), member.sheetId(), member.sheetId());
    }
}
package net.officefloor.hq.app.crew;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Repository;

/** The store of the sheet's crews and their members. */
@Repository
public class Crews {

    private final JdbcTemplate jdbc;

    public Crews(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's crews, in the order they were added, each with its members' ids in the order they were added. */
    public List<CrewResponse> list(String sheetId) {
        Map<String, Long> leads = new LinkedHashMap<>();
        jdbc.query("SELECT name, lead_id FROM crew WHERE sheet_id = ? ORDER BY listed",
                (RowCallbackHandler) rs -> leads.put(rs.getString("name"), rs.getLong("lead_id")), sheetId);
        Map<String, List<Long>> members = new LinkedHashMap<>();
        jdbc.query("SELECT crew_name, person_id FROM crew_member WHERE sheet_id = ? ORDER BY listed",
                (RowCallbackHandler) rs -> members.computeIfAbsent(rs.getString("crew_name"), k -> new ArrayList<>())
                        .add(rs.getLong("person_id")),
                sheetId);
        List<CrewResponse> out = new ArrayList<>();
        leads.forEach((name, lead) -> out.add(new CrewResponse(name, lead, members.getOrDefault(name, List.of()))));
        return out;
    }

    /** The crew's lead's id, null when the sheet has no such crew. */
    public Long lead(String sheetId, String name) {
        List<Long> found = jdbc.queryForList("SELECT lead_id FROM crew WHERE sheet_id = ? AND name = ?", Long.class,
                sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    public boolean has(String sheetId, String name) {
        return lead(sheetId, name) != null;
    }

    public void add(Crew crew) {
        jdbc.update("INSERT INTO crew (sheet_id, name, lead_id, listed) VALUES (?, ?, ?, "
                + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM crew WHERE sheet_id = ?))",
                crew.sheetId(), crew.name(), crew.leadId(), crew.sheetId());
    }

    public boolean isMember(String sheetId, String crew, long personId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM crew_member WHERE sheet_id = ? AND crew_name = ? AND person_id = ?", Integer.class,
                sheetId, crew, personId);
        return n != null && n > 0;
    }

    public void addMember(CrewMember member) {
        jdbc.update("INSERT INTO crew_member (sheet_id, crew_name, person_id, listed) VALUES (?, ?, ?, "
                + "(SELECT COALESCE(MAX(listed), 0) + 1 FROM crew_member WHERE sheet_id = ?))",
                member.sheetId(), member.crew(), member.personId(), member.sheetId());
    }
}

