import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { sumDue } from '../rates/ratesQuery';
import { poolsQuery } from './poolsQuery';
import type { Pool } from './poolsQuery';

/** A person's cut total: their cut in every pool they are a member of, added up; a pool that shows no cut adds nothing. */
function cutTotal(pools: Pool[], personId: number): string {
  const cuts = pools.flatMap((p) => p.members.filter((m) => m.pool === null && m.personId === personId && m.cut !== '').map((m) => m.cut));
  return sumDue(cuts);
}

function PersonCutTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const pools = useQuery(poolsQuery(sheetId)).data ?? [];
  return <td data-testid="person-cut-total">{cutTotal(pools, personId)}</td>;
}

/** The sheet's cut total: everyone's cut total added up. */
function CutTotal({ sheetId }: { sheetId: string }) {
  const pools = useQuery(poolsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  return (
    <p data-testid="rollup-cut">
      Cut total <strong data-testid="rollup-cut-total">{sumDue(people.map((p) => cutTotal(pools, p.id)))}</strong>
    </p>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 22.5, Component: () => <th>Cuts</th> }),
  PersonCells.fill({ order: 22.5, Component: PersonCutTotal }),
  SheetPanel.fill({ order: 25.6, Component: CutTotal }),
];
import { useQueryClient } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { poolsQuery } from './poolsQuery';

/** Downloads the pools as CSV: one line per member, pools and members in the order added, a pool member as pool:<name>
 *  and the cut as shown (empty when none). The pools are re-read first, so the file holds what the store holds now. */
function ExportPools({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();

  const exportCsv = async () => {
    const pools = await queryClient.fetchQuery({ ...poolsQuery(sheetId), staleTime: 0 });
    downloadCsv('pools.csv', [
      ['pool', 'member', 'share', 'cut'],
      ...pools.flatMap((p) => p.members.map((m) => [p.name, m.pool === null ? m.name : `pool:${m.pool}`, m.share, m.cut])),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void exportCsv()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 6.81, Component: ExportPools });
import { getJson } from '../../api/http';
import { peopleKey } from '../people/peopleQuery';

/** A member of a pool: the person's id and name, their share percent with two decimals, whether they are retired, and their
 *  cut of the pool's pot with two decimals ("" when the pool is not balanced, there is no pot, every member is retired, or the member's dates do
 *  not include the sheet's today). A member that is
 *  another pool has its name as pool (null for a person) and personId 0; its cut is that pool's pot. */
export type PoolMember = { personId: number; name: string; share: string; retired: boolean; cut: string; pool: string | null };

/** A pool of the sheet: its name, its members, its total share (a retired member's counting as given) with two decimals,
 *  and whether that total is exactly 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

/** Under the people's key, so re-loading the sheet, or any change to its people (a retirement), re-reads the pools. */
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'] as const;

export const poolsQuery = (sheetId: string) => ({
  queryKey: poolsKey(sheetId),
  queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useUser } from '../session/useUser';
import { peopleQuery } from '../people/peopleQuery';
import type { Person } from '../people/peopleQuery';
import { poolsKey, poolsQuery } from './poolsQuery';
import type { Pool } from './poolsQuery';

/** One pool's row: its total share and whether it is balanced, its members with their shares, and the form a member is
 *  added through. A member is a person, or another pool chosen as pool:<name>. A person already in the pool, a pool
 *  already in a pool, a chain that loops or is more than three deep, a bad share, or a to-date before the from-date, is refused with an error on the pool. */
function PoolRow({ sheetId, pool, people, poolNames }: { sheetId: string; pool: Pool; people: Person[]; poolNames: string[] }) {
  const queryClient = useQueryClient();
  const [personId, setPersonId] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { pool: string; personId: number | null; memberPool: string | null; share: string; from: string; to: string }) =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/pool-members`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
      setPersonId('');
      setShare('');
      setFrom('');
      setTo('');
    },
    onError: (e: Error) => setError(e instanceof RefusedError ? e.message : 'The member could not be added.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
